package benchsandbox

import (
	"reflect"
	"testing"
)

func eq(t *testing.T, got, want []string) {
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v want %v", got, want)
	}
}
func TestPlain(t *testing.T)    { eq(t, ParseCSVLine("a,b,c"), []string{"a", "b", "c"}) }
func TestQuoted(t *testing.T)   { eq(t, ParseCSVLine(`a,"b,c",d`), []string{"a", "b,c", "d"}) }
func TestEscaped(t *testing.T)  { eq(t, ParseCSVLine(`"a""b"`), []string{`a"b`}) }
func TestTrailing(t *testing.T) { eq(t, ParseCSVLine("a,"), []string{"a", ""}) }
